//! Rebuild-layer tests: decode each non-Vorbis fixture and verify the WAV body
//! is byte-identical to the output of the upstream Fmod5Sharp rebuilders.
//!
//! The `tests/golden/*.body.bin` files are the audio bodies (everything after
//! the 38-byte WAV header) emitted by Fmod5Sharp's `FmodPcmRebuilder`,
//! `FmodGcadPcmRebuilder`, and `FmodImaAdPcmRebuilder` for these fixtures. They
//! were generated by a throwaway C# dumper against the upstream library, so a
//! byte-for-byte match proves our decoders reproduce the C# output exactly.
//!
//! We compare bodies rather than whole WAVs because NAudio's `WaveFileWriter`
//! leaves the RIFF/data size fields zero in several rebuilder code paths (a
//! `MemoryStream.GetBuffer()`/`ToArray()` dispose-ordering quirk); our writer
//! fills them in correctly, which is a deliberate improvement, not a regression.

use fsb_rs::{
    AudioType, Chunk, ChunkData, ChunkType, RebuildError, RebuiltAudio, Sample, SampleMetadata,
};

/// Load a fixture from `tests/fixtures/`.
fn fixture(name: &str) -> Vec<u8> {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(name);
    std::fs::read(&path).unwrap_or_else(|e| panic!("failed to read fixture {name}: {e}"))
}

/// Load a golden audio body from `tests/golden/`.
fn golden_body(name: &str) -> Vec<u8> {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/golden")
        .join(format!("{name}.body.bin"));
    std::fs::read(&path).unwrap_or_else(|e| panic!("failed to read golden {name}: {e}"))
}

/// The decoded audio samples of a rebuilt WAV: the `data` chunk body, i.e. the
/// bytes from offset 46 onward (RIFF/WAVE + 18-byte `fmt ` chunk + 8-byte
/// `data`/size header = 46). These are the PCM sample bytes we compare against
/// the upstream golden bodies, which Fmod5Sharp dumped as `wav[38..]` (i.e.
/// including their 8-byte `data`+size prefix), so the golden sample bytes start
/// at golden-body offset 8 — see [`golden_samples`].
fn wav_samples(wav: &[u8]) -> &[u8] {
    &wav[46..]
}

/// The decoded audio samples within a golden body (`wav[38..]`): skip the
/// 8-byte `data`+size prefix.
fn golden_samples(name: &str) -> Vec<u8> {
    let body = golden_body(name);
    body[8..].to_vec()
}

fn rebuild_first(fixture_name: &str) -> RebuiltAudio {
    let bytes = fixture(fixture_name);
    let bank = fsb_rs::parse(&bytes).expect("fixture should parse");
    bank.rebuild_sample(0).expect("rebuild should succeed")
}

fn synthetic_sample<'a>(
    data: &'a [u8],
    sample_count: u32,
    channels: u32,
    frequency_id: u32,
    chunks: Vec<Chunk>,
) -> Sample<'a> {
    Sample {
        metadata: SampleMetadata {
            sample_count,
            channels,
            is_stereo: channels == 2,
            data_offset: 0,
            has_any_chunks: !chunks.is_empty(),
            frequency_id,
            chunks,
        },
        sample_bytes: data,
        name: None,
    }
}

// ---------- PCM ----------

#[test]
fn rebuilds_pcm16_matching_upstream() {
    let bytes = fixture("pcm16.fsb");
    let bank = fsb_rs::parse(&bytes).expect("pcm16 should parse");
    assert_eq!(bank.header.audio_type, AudioType::Pcm16);

    let audio = bank.rebuild_sample(0).expect("rebuild");
    let wav = match audio {
        RebuiltAudio::Wav(w) => w,
        other => panic!("expected WAV, got {other:?}"),
    };
    assert_eq!(wav_samples(&wav), golden_samples("pcm16").as_slice());
}

#[test]
fn rebuilds_synthetic_pcm8_exactly() {
    let data = [0x00, 0x7f, 0x80, 0xff];
    let sample = synthetic_sample(&data, 4, 1, 8, vec![]);
    let wav = sample.rebuild(AudioType::Pcm8).unwrap().into_bytes();

    assert_eq!(u16::from_le_bytes(wav[22..24].try_into().unwrap()), 1);
    assert_eq!(u16::from_le_bytes(wav[34..36].try_into().unwrap()), 8);
    assert_eq!(u32::from_le_bytes(wav[42..46].try_into().unwrap()), 4);
    assert_eq!(wav_samples(&wav), data);
}

#[test]
fn rebuilds_synthetic_stereo_pcm32_exactly() {
    let values = [i32::MIN, -1, 0, i32::MAX];
    let data: Vec<u8> = values
        .iter()
        .flat_map(|value| value.to_le_bytes())
        .collect();
    let sample = synthetic_sample(&data, 2, 2, 9, vec![]);
    let wav = sample.rebuild(AudioType::Pcm32).unwrap().into_bytes();

    assert_eq!(u16::from_le_bytes(wav[22..24].try_into().unwrap()), 2);
    assert_eq!(u32::from_le_bytes(wav[24..28].try_into().unwrap()), 48_000);
    assert_eq!(u16::from_le_bytes(wav[32..34].try_into().unwrap()), 8);
    assert_eq!(u16::from_le_bytes(wav[34..36].try_into().unwrap()), 32);
    assert_eq!(u32::from_le_bytes(wav[42..46].try_into().unwrap()), 16);
    assert_eq!(wav_samples(&wav), data);
}

#[test]
fn pcm_rejects_data_shorter_than_declared_samples() {
    let sample = synthetic_sample(&[0; 7], 1, 2, 8, vec![]);
    assert!(matches!(
        sample.rebuild(AudioType::Pcm32),
        Err(RebuildError::SampleDataTooShort)
    ));
}

#[test]
fn multichannel_pcm_matches_upstream_mono_fallback() {
    let data = [0u8; 12];
    let sample = synthetic_sample(&data, 1, 6, 8, vec![]);
    let wav = sample.rebuild(AudioType::Pcm16).unwrap().into_bytes();

    assert_eq!(u16::from_le_bytes(wav[22..24].try_into().unwrap()), 1);
    assert_eq!(u32::from_le_bytes(wav[42..46].try_into().unwrap()), 2);
}

#[test]
fn overflowing_wav_format_returns_error() {
    let data = [0u8; 2];
    let sample = synthetic_sample(&data, 1, 1, u32::MAX, vec![]);
    let err = sample.rebuild(AudioType::Pcm16).unwrap_err();

    assert!(matches!(err, RebuildError::OutputTooLarge));
}

// ---------- GCADPCM ----------

#[test]
fn rebuilds_gcadpcm_matching_upstream() {
    let bytes = fixture("gcadpcm.fsb");
    let bank = fsb_rs::parse(&bytes).expect("gcadpcm should parse");
    assert_eq!(bank.header.audio_type, AudioType::Gcadpcm);

    let audio = bank.rebuild_sample(0).expect("rebuild");
    let wav = match audio {
        RebuiltAudio::Wav(w) => w,
        other => panic!("expected WAV, got {other:?}"),
    };
    assert_eq!(wav_samples(&wav), golden_samples("gcadpcm").as_slice());
}

#[test]
fn gcadpcm_extreme_coefficients_do_not_overflow() {
    let data = [0x0f, 0x77, 0x77, 0x77, 0x77, 0x77, 0x77, 0x77];
    let coeff_chunk = Chunk {
        chunk_type: ChunkType::DspCoeff,
        more: false,
        data: ChunkData::DspCoefficients {
            channel_data: vec![vec![i16::MAX; 16]],
        },
    };
    let sample = synthetic_sample(&data, 14, 1, 8, vec![coeff_chunk]);

    assert!(sample.rebuild(AudioType::Gcadpcm).is_ok());
}

#[test]
fn rebuilds_synthetic_stereo_gcadpcm_exactly() {
    // Predictor 0, scale 1, and zero coefficients make each PCM value equal
    // the signed nibble. Two coefficient sets exercise stereo chunk parsing;
    // like upstream, the decoder uses the first set for this packed stream.
    let data = [0x00, 0x12, 0x34, 0x56, 0x78, 0x9a, 0xbc, 0xde];
    let coeff_chunk = Chunk {
        chunk_type: ChunkType::DspCoeff,
        more: false,
        data: ChunkData::DspCoefficients {
            channel_data: vec![vec![0; 16], vec![0; 16]],
        },
    };
    let sample = synthetic_sample(&data, 14, 2, 8, vec![coeff_chunk]);
    let wav = sample.rebuild(AudioType::Gcadpcm).unwrap().into_bytes();
    let decoded: Vec<i16> = wav_samples(&wav)
        .chunks_exact(2)
        .map(|bytes| i16::from_le_bytes([bytes[0], bytes[1]]))
        .collect();

    assert_eq!(u16::from_le_bytes(wav[22..24].try_into().unwrap()), 2);
    assert_eq!(decoded, [1, 2, 3, 4, 5, 6, 7, -8, -7, -6, -5, -4, -3, -2]);
}

// ---------- IMA ADPCM ----------

#[test]
fn rebuilds_imaadpcm_short_matching_upstream() {
    let audio = rebuild_first("imaadpcm_short.fsb");
    let wav = match audio {
        RebuiltAudio::Wav(w) => w,
        other => panic!("expected WAV, got {other:?}"),
    };
    assert_eq!(
        wav_samples(&wav),
        golden_samples("imaadpcm_short").as_slice()
    );
}

