#[test]
fn rebuilds_xbox_imaad_matching_upstream() {
    // xbox_imaad is mono -> exercises the Xbox-IMA path.
    let bytes = fixture("xbox_imaad.fsb");
    let bank = fsb_rs::parse(&bytes).expect("xbox_imaad should parse");
    for s in &bank.samples {
        assert_eq!(s.metadata.channels, 1, "xbox_imaad is mono");
    }

    let audio = bank.rebuild_sample(0).expect("rebuild");
    let wav = match audio {
        RebuiltAudio::Wav(w) => w,
        other => panic!("expected WAV, got {other:?}"),
    };
    assert_eq!(wav_samples(&wav), golden_samples("xbox_imaad").as_slice());
}

#[test]
fn ima_rejects_huge_declared_output_before_allocating() {
    let data = [0u8; 4];
    let sample = synthetic_sample(&data, (1 << 30) - 1, 1, 8, vec![]);
    let err = sample.rebuild(AudioType::ImaAdpcm).unwrap_err();

    assert!(matches!(err, RebuildError::SampleDataTooShort));
}

#[test]
fn ima_rejects_inconsistent_channel_metadata_without_panicking() {
    let data = [0u8; 0x24 * 8];
    let mut sample = synthetic_sample(&data, 64, 8, 8, vec![]);
    sample.metadata.is_stereo = true;

    let err = sample.rebuild(AudioType::ImaAdpcm).unwrap_err();
    assert!(matches!(err, RebuildError::InvalidChannelCount(8)));
}

#[test]
fn ima_rejects_inconsistent_stereo_flag() {
    let data = [0u8; 0x24 * 2];
    let mut sample = synthetic_sample(&data, 64, 2, 8, vec![]);
    sample.metadata.is_stereo = false;

    let err = sample.rebuild(AudioType::ImaAdpcm).unwrap_err();
    assert!(matches!(err, RebuildError::InvalidChannelCount(2)));
}

// ---------- Vorbis ----------

#[test]
fn rebuilds_all_vorbis_fixtures_as_valid_ogg() {
    for name in [
        "short_vorbis.fsb",
        "long_vorbis.fsb",
        "vorbis_with_blockflag_exception.fsb",
        "previously_unrecoverable_vorbis.fsb",
    ] {
        let bytes = fixture(name);
        let bank = fsb_rs::parse(&bytes).expect("Vorbis fixture should parse");
        let sample_count = u64::from(bank.samples[0].metadata.sample_count);
        let ogg = match bank
            .rebuild_sample(0)
            .expect("Vorbis rebuild should succeed")
        {
            RebuiltAudio::Ogg(bytes) => bytes,
            other => panic!("expected Ogg, got {other:?}"),
        };

        let mut reader = ogg::PacketReader::new(std::io::Cursor::new(ogg.clone()));
        let mut packets = Vec::new();
        while let Some(packet) = reader.read_packet().expect("valid Ogg pages and CRCs") {
            packets.push(packet);
        }
        assert!(packets.len() > 3, "{name} should contain audio packets");
        assert_eq!(&packets[0].data[..7], b"\x01vorbis");
        assert_eq!(&packets[1].data[..7], b"\x03vorbis");
        assert_eq!(&packets[2].data[..7], b"\x05vorbis");
        let last = packets.last().unwrap();
        assert!(last.last_in_stream(), "{name} must carry EOS");
        assert_eq!(last.absgp_page(), sample_count, "{name} granule position");

        let mut decoder =
            lewton::inside_ogg::OggStreamReader::new(std::io::Cursor::new(ogg.clone()))
                .expect("Vorbis headers should decode");
        let mut decoded = 0usize;
        while let Some(samples) = decoder
            .read_dec_packet_itl()
            .expect("Vorbis audio packets should decode")
        {
            decoded += samples.len();
        }
        let channels = bank.samples[0].metadata.channels as usize;
        let declared_samples = sample_count as usize * channels;
        assert!(
            decoded >= declared_samples,
            "{name} must decode enough PCM for the declared sample count"
        );
        assert!(
            decoded - declared_samples < 2_048 * channels,
            "{name} may only exceed the final granule by one Vorbis long block"
        );
    }
}

#[test]
fn invalid_sample_index_returns_error() {
    let bytes = fixture("pcm16.fsb");
    let bank = fsb_rs::parse(&bytes).expect("pcm16 should parse");
    let err = bank.rebuild_sample(usize::MAX).unwrap_err();

    assert!(matches!(
        err,
        RebuildError::InvalidSampleIndex(i) if i == usize::MAX
    ));
}

// ---------- WAV header correctness ----------
//
// NAudio leaves size fields zero in several rebuilder paths; our writer fills
// them in. Assert the header is a well-formed, self-consistent PCM WAV.

#[test]
fn wav_header_is_well_formed() {
    let audio = rebuild_first("pcm16.fsb");
    let wav = match audio {
        RebuiltAudio::Wav(w) => w,
        other => panic!("expected WAV, got {other:?}"),
    };

    assert_eq!(&wav[..4], b"RIFF");
    assert_eq!(&wav[8..12], b"WAVE");
    assert_eq!(&wav[12..16], b"fmt ");
    let riff_size = u32::from_le_bytes(wav[4..8].try_into().unwrap()) as usize;
    assert_eq!(
        riff_size + 8,
        wav.len(),
        "RIFF size must be file length - 8"
    );

    let data_idx = wav
        .windows(4)
        .position(|w| w == b"data")
        .expect("data chunk present");
    let data_size =
        u32::from_le_bytes(wav[data_idx + 4..data_idx + 8].try_into().unwrap()) as usize;
    assert_eq!(
        data_size,
        wav.len() - (data_idx + 8),
        "data size must cover the remaining body"
    );
}

// ---------- FADPCM synthetic golden tests (no upstream fixture) ----------
//
// There is no FADPCM fixture upstream, so use frames whose output can be
// calculated directly from the upstream formula.

#[test]
fn fadpcm_zero_frame_decodes_to_exact_silence() {
    // Build a metadata word + 0x8C-byte frame for a 1-channel sample.
    // Frame header: coefs_lookup=0 (-> coefs [0,0] for all groups), shifts=0,
    // hist1=0, hist2=0, then zero nibbles. With zero history and zero coefs,
    // every sample decodes to 0.
    let frame = vec![0u8; 0x8C];
    let bytes = build_single_frame_fadpcm_bank(&frame);
    let bank = fsb_rs::parse(&bytes).expect("synthetic FADPCM bank parses");
    assert_eq!(bank.header.audio_type, AudioType::Fadpcm);
    let audio = bank.rebuild_sample(0).expect("rebuild");
    let wav = match audio {
        RebuiltAudio::Wav(w) => w,
        other => panic!("expected WAV, got {other:?}"),
    };
    // With zero coefs/history/nibbles, every decoded sample is 0.
    let samples = wav_samples(&wav);
    assert_eq!(samples.len(), 256 * 2);
    assert_eq!(samples, vec![0; 256 * 2]);
}

#[test]
fn fadpcm_nibbles_decode_to_expected_signed_pcm() {
    // coef index 0 and shift 0 reduce the formula to the signed nibble itself.
    // The first u32 contains nibbles 0..7 in decode order, followed by a u32
    // containing -8..-1. Remaining groups are zero.
    let mut frame = vec![0u8; 0x8C];
    frame[0x0c..0x10].copy_from_slice(&0x7654_3210u32.to_le_bytes());
    frame[0x10..0x14].copy_from_slice(&0xfedc_ba98u32.to_le_bytes());
    let bytes = build_single_frame_fadpcm_bank(&frame);
    let bank = fsb_rs::parse(&bytes).expect("synthetic FADPCM bank parses");
    let wav = bank.rebuild_sample(0).expect("rebuild").into_bytes();
    let decoded: Vec<i16> = wav_samples(&wav)
        .chunks_exact(2)
        .map(|bytes| i16::from_le_bytes([bytes[0], bytes[1]]))
        .collect();

    assert_eq!(decoded.len(), 256);
    assert_eq!(
        &decoded[..16],
        &[0, 1, 2, 3, 4, 5, 6, 7, -8, -7, -6, -5, -4, -3, -2, -1]
    );
    assert!(decoded[16..].iter().all(|sample| *sample == 0));
}

/// Hand-build a minimal single-sample FADPCM bank whose data region is `frame`.
fn build_single_frame_fadpcm_bank(frame: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    out.extend_from_slice(b"FSB5");
    out.extend_from_slice(&1u32.to_le_bytes()); // version
    out.extend_from_slice(&1u32.to_le_bytes()); // num_samples
    out.extend_from_slice(&8u32.to_le_bytes()); // size_of_sample_headers (1 * 8 bytes)
    out.extend_from_slice(&0u32.to_le_bytes()); // size_of_name_table
    out.extend_from_slice(&(frame.len() as u32).to_le_bytes()); // size_of_data
    out.extend_from_slice(&16u32.to_le_bytes()); // audio_type = FADPCM
    out.extend_from_slice(&0u32.to_le_bytes()); // 0x1C always 0
    out.extend_from_slice(&0u32.to_le_bytes()); // flags
    out.extend_from_slice(&0u64.to_le_bytes()); // hash lower
    out.extend_from_slice(&0u64.to_le_bytes()); // hash upper
    out.extend_from_slice(&0u64.to_le_bytes()); // unknown u64
    debug_assert_eq!(out.len(), 0x3C);

    // Sample metadata word: has_any_chunks=0, freq_id=8 (44100), channels=1
    // (channel code 0), data_offset=0, sample_count=(0x8C-0x0C)*2 = 256.
    let mut encoded = 0u64;
    encoded |= 8 << 1; // freq_id 8
    encoded |= (256u64) << 34; // sample_count
    out.extend_from_slice(&encoded.to_le_bytes());

    out.extend_from_slice(frame);
    out
}
